(()=>{'use strict';const box=document.querySelector('#chimeraTerminalOutput'),input=document.querySelector('#chimeraTerminalInput'),form=document.querySelector('#chimeraTerminalForm');if(!box||!input||!form)return;let history=[],hi=0,cwd='/home/chimera';const vars={USER:'chimera',HOME:'/home/chimera',PWD:cwd},tables=new Map;const out=s=>{const d=document.createElement('div');d.textContent=String(s);box.appendChild(d);box.scrollTop=box.scrollHeight};const resolve=p=>{p=p||cwd;if(p==='~')return vars.HOME;if(p.startsWith('~/'))p=vars.HOME+p.slice(1);const r=[];for(const x of (p.startsWith('/')?p:cwd+'/'+p).split('/')){if(!x||x==='.')continue;if(x==='..')r.pop();else r.push(x)}return'/'+r.join('/')};const tok=s=>{const a=[];let b='',q='';for(const c of s){if(q){if(c===q)q='';else b+=c}else if(c==='"'||c==="'")q=c;else if(/\s/.test(c)){if(b){a.push(b);b=''}}else b+=c}if(b)a.push(b);return a};function sql(s){s=s.trim().replace(/;$/,'');let m=s.match(/^create\s+table\s+(\w+)\s*\(([^)]+)\)$/i);if(m){if(tables.has(m[1]))return['table already exists',false];tables.set(m[1],{cols:m[2].split(',').map(x=>x.trim().split(/\s+/)[0]),rows:[]});return['CREATE TABLE',true]}m=s.match(/^insert\s+into\s+(\w+)\s*\(([^)]+)\)\s*values\s*\(([^)]+)\)$/i);if(m){const t=tables.get(m[1]);if(!t)return['table not found',false];const vals=m[3].split(',').map(x=>x.trim().replace(/^['"]|['"]$/g,'')),cols=m[2].split(',').map(x=>x.trim()),row=Object.fromEntries(t.cols.map(c=>[c,null]));cols.forEach((c,i)=>row[c]=vals[i]??null);t.rows.push(row);return['INSERT 1',true]}m=s.match(/^select\s+(.+?)\s+from\s+(\w+)(?:\s+where\s+(\w+)\s*=\s*['"]?([^'"]+)['"]?)?$/i);if(m){const t=tables.get(m[2]);if(!t)return['table not found',false];const cols=m[1].trim()==='*'?t.cols:m[1].split(',').map(x=>x.trim()),rows=m[3]?t.rows.filter(r=>String(r[m[3]])===m[4]):t.rows;return[[cols.join('\t'),...rows.map(r=>cols.map(c=>r[c]??'NULL').join('\t'))].join('\n')||'(0 rows)',true]}if(/^show\s+tables$/i.test(s))return[[...tables.keys()].join('\n')||'(no tables)',true];m=s.match(/^(?:describe|desc)\s+(\w+)$/i);if(m){const t=tables.get(m[1]);return[t?t.cols.join('  '):'table not found',!!t]}m=s.match(/^drop\s+table\s+(\w+)$/i);if(m){tables.delete(m[1]);return['DROP TABLE',true]}return['SQL syntax not supported by the built-in in-memory engine',false]};const one=raw=>{const t=tok(raw.trim()),c=(t.shift()||'').toLowerCase(),a=t.join(' ');if(c==='sql'||c==='sqlite'||c==='sqlite3')return sql(a);if(c==='help'||c==='man')return['Chimera terminal: POSIX/Bash/Zsh/Fish/Dash/Ksh/Csh/Tcsh + CMD + PowerShell compatibility. SQL: CREATE/INSERT/SELECT/SHOW/DESCRIBE/DROP. Host execution is disabled.',true];if(c==='pwd'||c==='get-location')return[cwd,true];if(c==='cd'||c==='set-location'){cwd=resolve(t[0]);vars.PWD=cwd;return['',true]}if(['echo','printf','write-output','write-host'].includes(c))return[a,true];if(c==='whoami')return['chimera',true];if(c==='hostname')return['chimera-aurora',true];if(c==='uname')return['Chimera II OS / N8192 / Koronos / Aurora Wayland',true];if(['bash','sh','zsh','fish','dash','ksh','csh','tcsh','cmd','powershell','pwsh'].includes(c))return[c+' shell compatibility mode active; native process execution requires a configured sandbox service',true];if(['rm','del','erase','format','shutdown','kill','sudo','restart-computer'].includes(c))return[c+': blocked in browser sandbox',false];return[c+': command not found. Type help.',false]};form.addEventListener('submit',e=>{e.preventDefault();e.stopImmediatePropagation();const raw=input.value.trim();if(!raw)return;history.push(raw);hi=history.length;out('chimera@aurora:'+cwd+'$ '+raw);out(one(raw)[0]);input.value=''},{capture:true});input.addEventListener('keydown',e=>{if(e.key==='ArrowUp'){e.preventDefault();hi=Math.max(0,hi-1);input.value=history[hi]||''}else if(e.key==='ArrowDown'){e.preventDefault();hi=Math.min(history.length,hi+1);input.value=history[hi]||''}})})();